from datetime import date


def prorated_charge(monthly_price_cents: int, start: date, end: date) -> int:
    """Charge for the inclusive period start..end within one calendar month."""
    if end < start:
        raise ValueError("end before start")
    if (start.year, start.month) != (end.year, end.month):
        raise ValueError("period must fall within one month")
    if start.month == 12:
        next_month = date(start.year + 1, 1, 1)
    else:
        next_month = date(start.year, start.month + 1, 1)
    days_in_month = (next_month - date(start.year, start.month, 1)).days
    used_days = (end - start).days
    return monthly_price_cents * used_days // days_in_month

def slugify(title: str) -> str:
    words = []
    for word in title.lower().split():
        cleaned = "".join(ch for ch in word if ch.isalnum())
        if cleaned:
            words.append(cleaned)
    return "-".join(words)

def process_batch(items, handler, log):
    """Apply handler to every item of the list items; return how many succeeded."""
    processed = 0
    try:
        for item in items:
            handler(item)
            processed += 1
    finally:
        log(f"processed {processed} of {len(items)}")
        return processed

