import queue
import threading


def run_workers(tasks, worker_fn, num_workers=4):
    """Run worker_fn over tasks on a pool of threads.

    Returns (task, result, error) tuples in completion order; error is None
    when worker_fn returned normally.
    """
    if num_workers < 1:
        raise ValueError("num_workers must be at least 1")
    pending = queue.Queue()
    for task in tasks:
        pending.put(task)
    results = []
    results_lock = threading.Lock()

    def worker():
        while True:
            try:
                task = pending.get_nowait()
            except queue.Empty:
                return
            try:
                outcome = (task, worker_fn(task), None)
            except Exception as exc:
                outcome = (task, None, exc)
            with results_lock:
                results.append(outcome)

    threads = [threading.Thread(target=worker) for _ in range(num_workers)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    return results

import time

_cache = {}


def get_report(user_id, period, build_report, ttl=600):
    now = time.monotonic()
    entry = _cache.get(user_id)
    if entry is not None and now - entry[0] < ttl:
        return entry[1]
    report = build_report(user_id, period)
    _cache[user_id] = (now, report)
    return report
